function StarRating({ rating }) {
  return (
    <div className="stars">
      {[1, 2, 3, 4, 5].map(star => (
        <span key={star} className="star">
          {star <= Math.round(rating) ? '★' : '☆'}
        </span>
      ))}
      <span className="rating-value">({rating})</span>
    </div>
  );
}
